function ItemDefinitions.GetIngotForOre(OreName)
	for _, Definition in ItemDefinitions.Ingots do
		if Definition.OreName == OreName then
			return Definition
		end
	end

	return nil
end

function ItemDefinitions.GetGemForOre(OreName)
	for _, Definition in ItemDefinitions.Gems do
		if Definition.OreName == OreName then
			return Definition
		end
	end

	return nil
end

return ItemDefinitions